package frc.robot.subsystems.Kicker;

import static frc.lib.SimTestUtil.runFor;
import static org.junit.jupiter.api.Assertions.assertEquals;

import org.junit.jupiter.api.AfterEach;
import org.junit.jupiter.api.BeforeAll;
import org.junit.jupiter.api.BeforeEach;
import org.junit.jupiter.api.Test;
import org.junit.jupiter.params.ParameterizedTest;
import org.junit.jupiter.params.provider.EnumSource;

import frc.lib.SimTestUtil;
import frc.robot.subsystems.Kicker.KickerConstants.SystemState;
import frc.robot.subsystems.Kicker.KickerConstants.WantedState;

/** Generated by 3161 Robot Setup: drives Kicker to every state in simulation. */
class KickerTest {
    private Kicker kicker;

    @BeforeAll
    static void setUpRobot() {
        SimTestUtil.setUpEnabledRobot();
    }

    @BeforeEach
    void create() {
        kicker = new Kicker();
    }

    @AfterEach
    void close() {
        kicker.close();
    }

    private void loop() {
        kicker.periodic();
        kicker.simulationPeriodic();
    }

    @ParameterizedTest
    @EnumSource(WantedState.class)
    void reachesEveryState(WantedState state) {
        kicker.setWantedState(state);
        runFor(3.0, this::loop);
        SystemState expected = state == WantedState.DEPLOY ? SystemState.BRAKE : SystemState.STOW;
        assertEquals(expected, kicker.getSystemState(),
                "Kicker didn't reach " + state + " -- check the gains and limits");
    }

    @Test
    void brakeIgnoresDeployButStows() {
        kicker.setWantedState(WantedState.DEPLOY);
        runFor(3.0, this::loop);
        assertEquals(SystemState.BRAKE, kicker.getSystemState());

        // Driver intake pressing DEPLOY again does nothing
        kicker.setWantedState(WantedState.DEPLOY);
        runFor(1.0, this::loop);
        assertEquals(SystemState.BRAKE, kicker.getSystemState());

        kicker.setWantedState(WantedState.STOW);
        runFor(3.0, this::loop);
        assertEquals(SystemState.STOW, kicker.getSystemState());
    }
}
